    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]    // below 50.00: base only, discount 249.95 -> 249
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]    // 50.00 joins the +1 band
    [InlineData(LoyaltyTier.Green, 10_000, 9_400)]
    [InlineData(LoyaltyTier.Green, 19_999, 18_799)]  // 199.99 stays in +1 band; discount 1199.94 -> 1199
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]  // 200.00 joins the +3 band
    [InlineData(LoyaltyTier.Gold, 4_999, 4_650)]
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_550)]
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)] // 9+1 = 10
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // 9+3 capped at 10
    [InlineData(LoyaltyTier.Green, 0, 0)]
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        var payable = new CalculatePayableTotal().For(subtotalCents, loyaltyTier);

        Assert.Equal(expectedPayableCents, payable);
    }
}
